// Extract added and modified files from each commit
const commit = $input.item.json;
const files = [
  ...(commit.added || []),
  ...(commit.modified || [])
];

// Filter to curriculum content files only
const curriculumFiles = files.filter(f => {
  const ext = f.split('.').pop()?.toLowerCase();
  return ['md', 'json', 'txt'].includes(ext || '');
});

return curriculumFiles.map(filename => ({
  json: {
    filename,
    repo: $('GitHub Webhook').item.json.repository.full_name,
    ref: $('GitHub Webhook').item.json.ref,
    commitSha: commit.id
  }
}));

// Determine document type and extract subject/grade from path
const filename = $json.filename || $json.path;
const ext = filename.split('.').pop()?.toLowerCase() || 'txt';

// Infer subject from directory structure
// Expected: curriculum/math/grade3/MGSE3.NF.1.md
const parts = filename.toLowerCase().split('/');
let subject = undefined;
let gradeLevel = [];
let standardCodes = [];

if (parts.some(p => p.includes('math'))) subject = 'MATH';
else if (parts.some(p => p.includes('science'))) subject = 'SCIENCE';
else if (parts.some(p => p.includes('ela') || p.includes('language'))) subject = 'LANGUAGE_ARTS';

const gradeMatch = filename.match(/grade(\d+)/i);
if (gradeMatch) gradeLevel = [parseInt(gradeMatch[1])];

// Extract standard codes from filename (e.g., MGSE3.NF.1.md)
const stdMatch = filename.match(/([A-Z]+\d+\.[A-Z]+\.\d+)/g);
if (stdMatch) standardCodes = stdMatch;

// Get file content (base64 decode if needed)
let content = $json.content || '';
if ($json.encoding === 'base64') {
  content = Buffer.from(content, 'base64').toString('utf-8');
}

return [{
  json: {
    filename: filename.split('/').pop(),
    content,
    documentType: ext,
    subject,
    gradeLevel,
    standardCodes,
    metadata: {
      sourcePath: filename,
      commitSha: $('Extract Changed Files').item.json.commitSha,
      repo: $('Extract Changed Files').item.json.repo
    }
  }
}];
